<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><nav class="breadcrumb"><a href="<?= url('/admin/dashboard') ?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Accounts</span><i data-lucide="chevron-right"></i><span>Chart of Accounts</span></nav><h1>Chart of Accounts</h1><p>Create and manage the categories used to classify income and expenses.</p></div></header><div class="split-layout"><form class="module-card" method="post" action="<?= url('/admin/accounts/heads') ?>"><?= csrf_field() ?><header class="module-card__header"><div><h2>Add Account Head</h2><p>Define a reusable ledger category.</p></div></header><div class="module-card__body"><div class="module-field"><label for="head">Head Name <span class="required">*</span></label><input class="module-input" id="head" name="head" maxlength="120" placeholder="e.g. Tuition Income" required></div><div class="module-field"><label for="type">Head Type <span class="required">*</span></label><select class="module-select" id="type" name="type" required><option value="">Select type</option><option value="income">Income</option><option value="expense">Expense</option><option value="both">Income &amp; Expense</option></select></div></div><footer class="module-card__footer"><button class="btn btn--primary" type="submit"><i data-lucide="save"></i>Save Account Head</button></footer></form><section class="module-card"><header class="module-card__header"><div><h2>Account Heads</h2><p><?= count($heads) ?> configured categor<?= count($heads)===1?'y':'ies' ?></p></div></header><div class="module-card__body"><?php if(!$heads):?><div class="compact-empty"><h3>No account heads yet</h3><p>Create the first category using the form.</p></div><?php else:?><div class="table-scroll"><table class="data-table"><thead><tr><th>Name</th><th>Type</th><th>Transactions</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($heads as$head):?><tr><td><strong><?= e($head['name']) ?></strong></td><td><span class="subject-badge"><?= e(ucwords($head['type'])) ?></span></td><td><?= (int)$head['transaction_count'] ?></td><td><span class="student-status student-status--<?= $head['status']==='active'?'active':'inactive' ?>"><?= e(ucfirst($head['status'])) ?></span></td><td><?php if((int)$head['transaction_count']===0):?><form method="post" action="<?= url('/admin/accounts/heads/'.$head['id'].'/delete') ?>"><?= csrf_field() ?><button class="class-action-button class-action-button--danger" type="submit" aria-label="Delete <?= e($head['name']) ?>"><i data-lucide="trash-2"></i></button></form><?php else:?><span class="text-muted">In use</span><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php endif?></div></section></div></div></div></main>
